import{_ as o,C as a,o as l,c as d,E as t,a2 as i}from"./chunks/framework.uPk2SrVb.js";const _=JSON.parse('{"title":"规则还在存储中，为何已不在模型上下文里","description":"","frontmatter":{"title":"规则还在存储中，为何已不在模型上下文里","date":"2026-10-28","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"规则仍在存储中，是否意味着它已进入模型上下文？","summary":"固定源码的函数隔离实验显示，历史窗口与摘要通过不同路径影响约束交付。保护条件需要落实到消息角色、位置和具体变换；存储状态与参数名称都不足以替代交付检查。","sources":["https://github.com/camel-ai/camel/blob/64b9a613d1c3f4606be64aa6b66ebca437e50cda/camel/memories/blocks/chat_history_block.py","https://github.com/camel-ai/camel/blob/64b9a613d1c3f4606be64aa6b66ebca437e50cda/camel/memories/context_creators/score_based.py","https://github.com/crewAIInc/crewAI/blob/76784a02f9a7342866d80400ffe067d1b3a28843/lib/crewai/src/crewai/llms/context_window.py"],"pageClass":"runtime-v6-article","item_id":"SIG-20261028-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-28-sig-20261028-003-2026-10-28-stored-rule-context-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-10-28-sig-20261028-003.md","filePath":"zh/engineering/2026-10-28-sig-20261028-003.md","lastUpdated":null}'),s={name:"zh/engineering/2026-10-28-sig-20261028-003.md"};function n(b,e,h,p,m,f){const r=a("ArticleCover"),c=a("ArticleTableScroll");return l(),d("div",null,[t(r,{image:"/assets/covers/daily-2026-10-28-sig-20261028-003-2026-10-28-stored-rule-context-cover.png",kicker:"研究成果",title:"规则还在存储中，为何已不在模型上下文里",summary:"固定源码的函数隔离实验显示，历史窗口与摘要通过不同路径影响约束交付。保护条件需要落实到消息角色、位置和具体变换；存储状态与参数名称都不足以替代交付检查。",version:"2026-10-28",languageHref:"/en/engineering/2026-10-28-sig-20261028-003",languageLabel:"English"}),t(c,{language:"zh"}),e[0]||(e[0]=i(`<h1 id="规则还在存储中-为何已不在模型上下文里" tabindex="-1">规则还在存储中，为何已不在模型上下文里 <a class="header-anchor" href="#规则还在存储中-为何已不在模型上下文里" aria-label="Permalink to &quot;规则还在存储中，为何已不在模型上下文里&quot;">​</a></h1><p>一条规则仍在三条记录组成的历史存储里，下一次取出的消息却只剩最近的助手回复。这是本次内部函数实验中的一个具体结果：存储没有被改写，规则却没有进入被测函数返回的上下文。检查数据库是否保存成功，回答不了模型接下来是否还能看到这条规则。</p><p>对维护智能体记忆与上下文压缩的工程师，关键问题因此是：哪一步变换负责把约束带到下一次调用？本次对两个开源框架的固定源码进行隔离探测，得到的有限判断是：约束交付要检查具体路径的结构性保护，不能从持久化、消息角色或参数名称直接推断。这里的“交付”仅指规则字符串出现在被测函数的输出消息中，还没有走到真实模型请求和动作执行。</p><h2 id="实验把边界放在哪里" tabindex="-1">实验把边界放在哪里 <a class="header-anchor" href="#实验把边界放在哪里" aria-label="Permalink to &quot;实验把边界放在哪里&quot;">​</a></h2><p>本次研究于 2026 年 10 月 28 日完成。CAMEL（开源智能体框架）的历史检索与上下文创建代码，以及 CrewAI（智能体协作框架）的摘要函数，分别固定到以下提交：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CAMEL   64b9a613d1c3f4606be64aa6b66ebca437e50cda</span></span>
<span class="line"><span>CrewAI  76784a02f9a7342866d80400ffe067d1b3a28843</span></span></code></pre></div><p>这些标识用于锁定源码，并不表示缺陷引入日期或某个线上版本的运行状态。<a href="https://github.com/camel-ai/camel/blob/64b9a613d1c3f4606be64aa6b66ebca437e50cda/camel/memories/blocks/chat_history_block.py" target="_blank" rel="noreferrer">历史检索源码</a>与<a href="https://github.com/crewAIInc/crewAI/blob/76784a02f9a7342866d80400ffe067d1b3a28843/lib/crewai/src/crewai/llms/context_window.py" target="_blank" rel="noreferrer">摘要源码</a>是实现事实的依据。</p><p>实验从抽象语法树中提取函数体，保留受测方法的实现；记录对象、存储、计数器以及摘要依赖由明确声明的适配对象替代。因此，这是一组源码函数探针，不是安装并运行两个完整框架。内部记录包含 36 个角色、位置与窗口组合，加上 1 个空历史对照、6 个上下文创建用例和 6 个受控摘要用例，共 49 个。它们是构造用例的覆盖范围，不是线上故障样本，也不能组成违规率的分母。</p><p>历史实验比较变换前后的存储内容，并检查固定规则标记是否出现在返回消息中。摘要实验则分别指定保留标记与省略标记的摘要输出，用于检验结构是否依赖摘要内容。我们没有调用真实摘要模型，没有执行外部动作，也没有判断改写后规则的语义等价性。</p><h2 id="历史窗口保护的不只是角色-还包括位置" tabindex="-1">历史窗口保护的不只是角色，还包括位置 <a class="header-anchor" href="#历史窗口保护的不只是角色-还包括位置" aria-label="Permalink to &quot;历史窗口保护的不只是角色，还包括位置&quot;">​</a></h2><p>被测历史检索方法先保护历史开头连续的 <code>system</code>（系统消息角色）和 <code>developer</code>（开发者消息角色）前缀，再对其余消息应用近期窗口。这里的“前缀”很关键：出现在普通消息之后的同名角色，不自动获得这项前缀保护。源码所显示的是选择返回记录的机制，不能据此说存储中的记录被删除了。<a href="https://github.com/camel-ai/camel/blob/64b9a613d1c3f4606be64aa6b66ebca437e50cda/camel/memories/blocks/chat_history_block.py" target="_blank" rel="noreferrer">历史检索实现</a></p><p>以下是内部实验中窗口设为 1、每组存储均有三条记录时的结果。位置从 0 起算；位置 1 的规则前面放置普通消息，因此不属于受保护前缀。<code>user</code>（用户消息角色）与 <code>assistant</code>（助手消息角色）分别用于普通输入和最近回复。</p><table tabindex="0"><thead><tr><th>规则角色与位置</th><th>输出中有规则标记吗</th><th>原存储改变了吗</th></tr></thead><tbody><tr><td>系统，位置 0</td><td>有</td><td>没有</td></tr><tr><td>系统，位置 1</td><td>没有</td><td>没有</td></tr><tr><td>开发者，位置 0</td><td>有</td><td>没有</td></tr><tr><td>开发者，位置 1</td><td>没有</td><td>没有</td></tr><tr><td>用户，位置 0 或 1</td><td>没有</td><td>没有</td></tr></tbody></table><p>来源：研究中心同日内部实验记录中的历史用例；属于隔离函数观察，未经独立复现。</p><p>系统规则在位置 1 的用例最能说明问题：存储仍有三条记录，输出仅有最近的助手回复。相反，位置 0 的系统或开发者规则在相同窗口下仍被保留。无窗口与负窗口对照保留了记录；窗口为 0 时只保留受保护前缀。两组事实共同限定结论：不能说“所有规则都会随历史变长而消失”，也不能只检查角色名称就宣称规则受到保护。</p><h2 id="名为分数与预算的接口-未必在这里裁剪" tabindex="-1">名为分数与预算的接口，未必在这里裁剪 <a class="header-anchor" href="#名为分数与预算的接口-未必在这里裁剪" aria-label="Permalink to &quot;名为分数与预算的接口，未必在这里裁剪&quot;">​</a></h2><p>随后还需要纠正一个容易接受的解释：是不是创建上下文时，低分的旧规则又被令牌预算挤掉了？在本次固定版本中，分数式上下文创建器（源码类名 <code>ScoreBasedContextCreator</code>）已不按分数或 <code>token_limit</code>（令牌上限参数）过滤检索到的记录。应以<a href="https://github.com/camel-ai/camel/blob/64b9a613d1c3f4606be64aa6b66ebca437e50cda/camel/memories/context_creators/score_based.py" target="_blank" rel="noreferrer">固定实现</a>为准，不能从类名反推当前行为。</p><p>内部实验向该创建器传入三条消息，在没有令牌计数缓存的路径中，把上限分别设为 1、10、10000，并反转分数排序。六个用例都返回了全部三条消息。测试计数器固定按每条消息 100 计数，故每次得到 300；这只是观察裁剪条件的人工量尺，不是真实模型的分词结果，更不是线上请求溢出的证据。</p><p>这一负结果收窄了诊断方向：本轮不能把遗漏归给这个创建器的分数淘汰。真实部署中是否由其他组件执行预算限制，仍要追踪实际调用路径。历史检索已经排除的规则，也不能凭“后面还有上下文创建器”就假定会自动补回来。</p><h2 id="摘要的区别在于改写-而不是选择" tabindex="-1">摘要的区别在于改写，而不是选择 <a class="header-anchor" href="#摘要的区别在于改写-而不是选择" aria-label="Permalink to &quot;摘要的区别在于改写，而不是选择&quot;">​</a></h2><p>另一条路径不是丢开旧记录，而是把工作消息改写成摘要。被测摘要函数把显式系统消息单独保留，其余消息进入摘要处理。这个结构性区分来自<a href="https://github.com/crewAIInc/crewAI/blob/76784a02f9a7342866d80400ffe067d1b3a28843/lib/crewai/src/crewai/llms/context_window.py" target="_blank" rel="noreferrer">摘要实现</a>，它本身没有为所有角色提供逐字保留的承诺。</p><p>内部实验为每种规则角色设置两种摘要替身：一种保留规则标记，另一种省略标记。观察结果如下。</p><table tabindex="0"><thead><tr><th>输入规则角色</th><th>保留标记的受控摘要后</th><th>省略标记的受控摘要后</th></tr></thead><tbody><tr><td>系统</td><td>标记仍在；原系统对象被保留</td><td>标记仍在；原系统对象被保留</td></tr><tr><td>开发者</td><td>标记存在于摘要中</td><td>标记不在输出中</td></tr><tr><td>用户</td><td>标记存在于摘要中</td><td>标记不在输出中</td></tr></tbody></table><p>来源：研究中心同日内部实验记录中的六个摘要用例；摘要由测试替身指定，不是真实模型生成。</p><p>系统消息没有依赖摘要替身来保住规则；开发者与用户消息则依赖摘要具体写了什么。保留标记的对照也很重要，它说明“摘要必然抹掉规则”同样不成立。本实验所呈现的是结构性依赖，并没有测量真实摘要模型多久会省略一次规则。开发者消息在进入这个函数之前还可能被其他路径规范化，本轮也未审计那些路径，不能由此宣告整个框架存在开发者通道漏洞。</p><h2 id="把一次-还在-拆成四项检查" tabindex="-1">把一次“还在”拆成四项检查 <a class="header-anchor" href="#把一次-还在-拆成四项检查" aria-label="Permalink to &quot;把一次“还在”拆成四项检查&quot;">​</a></h2><p>历史窗口通过选择记录改变输出，摘要通过改写内容改变输出。两者可比较的是约束经过变换后的存在条件，不是哪个框架更安全。我们的研究解释是，排查约束失效时应分别记录四项事实：</p><ol><li>规则是否仍在存储中；</li><li>规则经过选择、组装、摘要后是否进入实际发出的上下文；</li><li>哪个主体有权修改、替换或覆盖这条规则；</li><li>模型及执行端最终是否遵守了它。</li></ol><p>本次函数探针只覆盖前两项中的局部机制。后两项没有被“输出里找到标记”替代。工程上可据此选择检查点：在具体变换前后保留规则身份、消息角色、位置和输出观察，再将其与真实调用及动作结果对齐。这是基于结果提出的检查方法，尚不是已实现并验证的通用治理方案。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文区分三种证据角色：项目公开源码直接支持固定版本的实现事实；研究中心内部实验支持所列构造输入下的函数输出；由这些观察推导的检查方法属于研究解释。源码由项目自身提供，内部实验由我们执行，两者都不构成第三方对本文主张的独立复现。引用也不表示项目或作者为本文结论背书。</p><ul><li>CAMEL 项目，历史消息块源码，固定提交 <code>64b9a613d1c3f4606be64aa6b66ebca437e50cda</code>，<a href="https://github.com/camel-ai/camel/blob/64b9a613d1c3f4606be64aa6b66ebca437e50cda/camel/memories/blocks/chat_history_block.py" target="_blank" rel="noreferrer">实现材料</a>。支持前缀与窗口机制。</li><li>同一项目、同一提交，<a href="https://github.com/camel-ai/camel/blob/64b9a613d1c3f4606be64aa6b66ebca437e50cda/camel/memories/context_creators/score_based.py" target="_blank" rel="noreferrer">上下文创建器源码</a>。支持本次对分数与预算裁剪解释的修正。</li><li>CrewAI 项目，固定提交 <code>76784a02f9a7342866d80400ffe067d1b3a28843</code>，<a href="https://github.com/crewAIInc/crewAI/blob/76784a02f9a7342866d80400ffe067d1b3a28843/lib/crewai/src/crewai/llms/context_window.py" target="_blank" rel="noreferrer">上下文窗口处理源码</a>。支持系统消息与待摘要消息的结构性区分。</li><li>研究中心，2026 年 10 月 28 日内部隔离实验记录及提取脚本，随候选材料保存，候选阶段访问受限。表格、用例集合与人工计数均来自该记录；本文没有声称其已成为公开独立复现包。源码快照也采集于当日，未据此推定最近发布变更。</li></ul><p>题图是根据历史窗口观察生成的编辑性概念图，不是函数输出或额外实验数据。正文没有另行制作解释图；精确条件由上述原生表格承担。</p><h2 id="还要沿真实调用追问什么" tabindex="-1">还要沿真实调用追问什么 <a class="header-anchor" href="#还要沿真实调用追问什么" aria-label="Permalink to &quot;还要沿真实调用追问什么&quot;">​</a></h2><p>固定标记存在，只能说明这个字符串穿过了受测变换。语义等价、合法覆盖、修改权限、模型服从以及执行端拦截均未测量；带缓存的计数和多模态路径也不在本轮范围内。我们没有复现先前论文的基准，更没有把其违规率移植到这两个框架。</p><p>下一步需要在真实部署的变换边界确认：谁决定消息角色与位置，谁能够修改权威规则，创建器之后究竟由哪个组件执行上下文预算限制？随后才是模型与动作实验——规则确实被交付时，是否仍会出现不合规动作？这两个问题应分别取证，不能把前一个检查通过当成后一个已经解决。</p>`,36))])}const g=o(s,[["render",n]]);export{_ as __pageData,g as default};
